import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay, Pagination } from "swiper/modules";
import "swiper/css";
import "swiper/css/pagination";

export default function Testimonials() {
  const testimonials = [
    {
      name: "علی رضایی",
      role: "کاربر بلیتو",
      image: "/users/user1.jpg",
      comment:
        "خیلی سریع بلیت پیدا کردم. قیمت‌ها دقیق و به‌روز بود. واقعاً تجربه خوبی داشتم.",
    },
    {
      name: "سمیه مهدوی",
      role: "کاربر بلیتو",
      image: "/users/user2.jpg",
      comment:
        "پشتیبانی خیلی خوبی داشتید، بدون دردسر بلیت رزرو کردم. ممنون از تیم خوبتون.",
    },
    {
      name: "مهدی صادقی",
      role: "کاربر بلیتو",
      image: "/users/user3.jpg",
      comment:
        "امکان مقایسه قیمت‌ها خیلی کمکم کرد. سریع‌ترین مسیرها رو راحت پیدا کردم.",
    },
  ];

  return (
    <div className="mt-20">
      <h2 className="text-3xl font-bold text-center text-slate-800 mb-10">
        نظرات کاربران درباره بلیتو
      </h2>

      <Swiper
        modules={[Autoplay, Pagination]}
        autoplay={{ delay: 2500, disableOnInteraction: false }}
        pagination={{ clickable: true }}
        loop={true}
        spaceBetween={30}
        slidesPerView={1}
        breakpoints={{
          768: { slidesPerView: 2 },
          1024: { slidesPerView: 3 },
        }}
      >
        {testimonials.map((item, i) => (
          <SwiperSlide key={i}>
            <div className="bg-white/70 backdrop-blur-md border-0 shadow-lg hover:shadow-xl transition-all duration-300 rounded-2xl p-8 text-center">
              
              {/* تصویر کاربر */}
              <div className="w-20 h-20 mx-auto mb-4 rounded-full overflow-hidden shadow-md">
                <img 
                  src={item.image} 
                  alt={item.name} 
                  className="w-full h-full object-cover"
                />
              </div>

              {/* متن */}
              <p className="text-slate-700 leading-relaxed mb-4">“{item.comment}”</p>

              {/* نام */}
              <h4 className="font-semibold text-slate-800">{item.name}</h4>
              <span className="text-sm text-slate-500">{item.role}</span>
            </div>
          </SwiperSlide>
        ))}
      </Swiper>
    </div>
  );
}
